namespace PipeDream;

/// <summary>
/// Lunar Magic's ExAnimation engine, transplanted (CONTRACT §12d-f, reference/EXANIMATION.md).
/// Bytes are LM's own from exanim_1.smc (engine at $108640, 0xC30; the two hook helpers at
/// $109880/$1098A8), moved into bank $1E behind the level-entry blocks. Diffing the same engine
/// in ShaoBase ($138000) showed every differing byte is a relocation: 16-bit in-bank operands
/// (incl. the 108-entry handler table at +B4A), six in-block long operands, the two long
/// operands that name the per-level pointer table (+DF = table+1, +EA = table), and the global
/// list's baked immediates (+5B bankword, +65 low16 — zero = no global list, patched by the
/// writer). Everything else — RAM ($7FC0xx), $03BCC0, the vanilla tables — is absolute.
///
/// Seven hook sites, all vanilla on a prepped base: $0583AD level setup → engine+0; $00A390 NMI
/// animated-tile DMA → engine+170 then RTS; $0095B6/$00A2A6/$00A5FE JSL $05BB39 (vanilla tile
/// animation) → engine+4B0 (the per-tick processor); $008A4E → the $7FC0C0 clear helper (which
/// re-executes the displaced REP #$30 : LDX #$1FFE); $00A5E1 → the MVN helper (displaced
/// LDA #$01EF : MVN). $03BCC0-CF is zeroed as LM does when it installs.
/// </summary>
internal static class LmExAnimEngine
{
    public const int Bank = LmLevelEntry.Bank;
    public const int EngineSnes = (Bank << 16) | 0x9400;                 // 0xC30 bytes
    public const int MvnSnes = (Bank << 16) | 0xA040;                    // 0x20
    public const int ClearSnes = (Bank << 16) | 0xA068;                  // 0x30
    /// <summary>The per-level record pointer table LM keeps as a RATS block: 3 bytes × 0x200
    /// levels, FF 00 00 = no ExAnimation. Rom.LmExAnimBase finds it through the engine's operand.</summary>
    public const int TableSnes = (Bank << 16) | 0xA0A0;                  // 0x600
    public const int SetupEntry = EngineSnes, DmaEntry = EngineSnes + 0x170, ProcEntry = EngineSnes + 0x4B0;
    /// <summary>Where LM had the engine in exanim_1 — the base every in-bank operand is relative to.</summary>
    private const int SourceSnes = 0x108640;

    private static readonly int[] InBankOperands =
        [0x550, 0x59B, 0x5BF, 0x5C3, 0x5D6, 0x63E, 0x6C4, 0x79E, 0x7AC, 0x825, 0x833, 0x8B0];
    private static readonly int[] LongOperands = [0x5B0, 0x601, 0xA7E, 0xAAA, 0xACF, 0xAF4];
    private const int HandlerTable = 0xB4A, HandlerTableEnd = 0xC22;    // 108 in-bank words
    public const int TablePlusOneOperand = 0xDF, TableOperand = 0xEA;
    public const int GlobalBankWord = 0x5B, GlobalLow16 = 0x65;

    public static byte[] Engine()
    {
        var b = Convert.FromHexString(HexEngine);
        int delta = (EngineSnes & 0xFFFF) - (SourceSnes & 0xFFFF);
        void Word(int at) { int v = (b[at] | b[at + 1] << 8) + delta; b[at] = (byte)v; b[at + 1] = (byte)(v >> 8); }
        foreach (int at in InBankOperands) Word(at);
        for (int at = HandlerTable; at < HandlerTableEnd; at += 2) Word(at);
        foreach (int at in LongOperands) { Word(at); b[at + 2] = Bank; }
        Put24(b, TablePlusOneOperand, TableSnes + 1);
        Put24(b, TableOperand, TableSnes);
        b[GlobalBankWord] = 0; b[GlobalBankWord + 1] = 0; b[GlobalLow16] = 0; b[GlobalLow16 + 1] = 0;
        return b;
    }

    public static byte[] Mvn() => Convert.FromHexString(HexMvn);
    public static byte[] Clear() => Convert.FromHexString(HexClear);

    public static byte[] EmptyTable()
    {
        var t = new byte[0x600];
        for (int i = 0; i < t.Length; i += 3) t[i] = 0xFF;
        return t;
    }

    public static IEnumerable<(int Snes, byte[] Bytes)> Hooks()
    {
        yield return (0x0583AD, [0x22, .. Addr(SetupEntry), 0xEA]);
        yield return (0x00A390, [0x22, .. Addr(DmaEntry), 0x60]);
        yield return (0x0095B6, Addr(ProcEntry));
        yield return (0x00A2A6, Addr(ProcEntry));
        yield return (0x00A5FE, Addr(ProcEntry));
        yield return (0x008A4E, [0x22, .. Addr(ClearSnes), 0xEA]);
        yield return (0x00A5E1, [0xEA, 0xEA, 0x22, .. Addr(MvnSnes)]);
        yield return (Rom.LmAltExGfxTable, new byte[16]);
    }

    private static byte[] Addr(int snes) => [(byte)snes, (byte)(snes >> 8), (byte)(snes >> 16)];
    private static void Put24(byte[] b, int at, int v) { b[at] = (byte)v; b[at + 1] = (byte)(v >> 8); b[at + 2] = (byte)(v >> 16); }

    private const string HexMvn = "AD9B0D29FF00C98000F007A9FF015400006BA9EF015400006B4C4D0001FFFFFF";
    private const string HexClear = "C230A900008FC0C07F8FC7C07F8FCEC07F8FD5C07F8FDCC07F8FE3C07F8FEAC07F8FF1C07FA2FE1F6BFFFFFFFFFFFFFF";
    private const string HexEngine = "";
}
